def run(out):
 out=Path(out).resolve();cfg=read(out/'config.json');q=read(out/'quality/quality.json');smoke={m:read(out/('smoke_'+m)/'result.json') for m in ('A','B')};check(q['passed'] and all(s['passed'] for s in smoke.values()),'Quality/smoke gate')
 check('65 passed' in (out/'monitor/final_tests.log').read_text(),'Final correctness tests');check(read(out/'checkpoint_verification.json')['passed'],'Final interface/checkpoint compatibility')
