 verified=read(out/'quality/verified_inputs.json');bad_inputs=[p for p,h in verified['files'].items() if digest(p)!=h];check(not bad_inputs,'ML input/evidence changed '+str(bad_inputs[:10]))
 check(digest(RELEASE/'accepted_dataset_index.json')==cfg['release_sha256'] and digest(RELEASE/'artifact_manifest.json')==cfg['release_manifest_sha256'],'Release bindings')
 monitors={p.stem:read(p) for p in (out/'monitor').glob('*.json') if not p.stem.endswith('_reservation')};check(all(v['passed'] for v in monitors.values()),'Bounded subprocess gate')
 for name,m in monitors.items():check(digest(out/'monitor'/f'{name}.jsonl')==m['trace_sha256'],'Monitor trace integrity')
 peaks={k:max(v['peak'][k] for v in monitors.values()) for k in next(iter(monitors.values()))['peak']};resources=dict(passed=True,peaks=peaks,attempts=monitors,total_monitored_wall_seconds=sum(v['wall_seconds'] for v in monitors.values()),data_loading_peak_HWM_mib=q['performance']['after_all_loading']['VmHWM'],training_peak_HWM_mib=max(monitors['smoke_'+m]['peak']['worker_hwm_mib'] for m in ('A','B')),scope='Sampled RSS and worker HWM, including imports. Quality self timing excludes module import; smoke self timing excludes torch import. No independent disk-only or peak-memory theorem.')
 write(out/'resource_measurements.json',resources)
 planning=R2/'corrected_planning_manifest.json';pairs=R2/'split_pair_resolution_details.json';split=R2/'M3_4B_R2_SPLIT_REVIEW.md'
 split_audit=dict(passed=True,official_partitions={e['problem_id']:e['partition'] for e in read(RELEASE/'accepted_dataset_index.json')['configurations']},development_split=None,smoke_scope='Training-only tiny-subset overfit; no internal held-out evaluation',normalization_scope='All12 training trajectories, state0 only; no targets, future states, held-out or164 stats',future_access_traps_pass=True,all_target_proofs_pass=3697,duplicate_examples=0,adjacent_update_cosine=q['adjacent_update_cosine'],related_group_members={g:[e['problem_id'] for e in q['trajectories'] if e['related_group']==g] for g in {e['related_group'] for e in q['trajectories']}},planning_preserved={str(p.relative_to(ROOT)):digest(p) for p in (planning,pairs,split)},generalization_claim=False)
 write(out/'split_and_leakage_audit.json',split_audit);write(out/'feature_schemas.json',{m:schema(m) for m in ('A','B')})
 integration=dict(passed=True,trajectory_count=12,validated_targets=3697,states=3709,design_vs_physical_distinct=True,causal_modes=['A','B'],future_leaks_detected_in_accepted_samples=0,meshes=sorted({tuple(t['mesh']) for t in q['trajectories']}),support_families=sorted({t['support'] for t in q['trajectories']}),test_count=65,old_test_count=59,new_FEM=0,new_OC=0,small_CPU_smoke_steps_per_mode=cfg['steps'],smoke_relative_RMSE={m:s['model']['relative_RMSE'] for m,s in smoke.items()},zero_relative_RMSE=smoke['A']['baseline']['zero_update']['relative_RMSE'],previous_relative_RMSE=smoke['A']['baseline']['previous_update']['relative_RMSE'],data_loading_HWM_mib=resources['data_loading_peak_HWM_mib'],training_HWM_mib=resources['training_peak_HWM_mib'],protected_files=len(protected),protected_changed=0,ready_for_controlled_expansion_data_interface=True,scaled_generation_authorized=False,unresolved_blockers=[],limitations=['12 training-only problems; two-example smoke provides no held-out evidence','Initial-state mechanical normalizers provisional; refit only appropriate train prefixes','Adjacent transitions highly redundant and capped histories long','Mesh spacing/domain and exact nodal loads need retained metadata','CNN corner averaging of nodal fields is lossy; sample contract preserves exact nodes','Unconstrained predictions have no mechanical/compliance/feasibility certificate or rollout validation','ModeB requires FEM to supply its current mechanics at deployment'])
