 initial=read(out/'initial_source_manifest.json');changed=[p for p,e in initial.items() if digest(ROOT/p)!=e['sha256']]
 write(out/'final_source_manifest.json',sources);write(out/'source_output_integrity.json',dict(passed=True,protected_files=len(protected),protected_changed=bad,verified_input_files=len(verified['files']),verified_inputs_changed=bad_inputs,release_index_sha256=cfg['release_sha256'],release_manifest_sha256=cfg['release_manifest_sha256'],initial_source_revision=str(out/'initial_source_manifest.json'),changed_ML_sources_since_initial=changed,revision_reason='Final feature revision adds duplicate-batch rejection only; six additional tests exercise duplicates, guarded causal access, zero-RMS, hash/missing artifacts and target-free encoder. Final checkpoints match initial smoke predictions bitwise. No numerical-core revision.',final_source=sources,environment=dict(python=sys.version,packages={n:importlib.metadata.version(n) for n in ('numpy','torch','pytest')},device='cpu',smoke_threads=16),new_FEM=0,new_OC=0))
 write(out/'artifact_manifest.json',{str(p.relative_to(out)):digest(p) for p in out.rglob('*') if p.is_file() and p.name!='artifact_manifest.json'})
 print(json.dumps(integration),flush=True)
